(()=>{const gm=T.$gameParty;const a=gm.battleMembers()[0];const t=window.__t||{};const out={};const fails=[];const CHK=(k,v)=>{out[k]=v;if(v!==true)fails.push(k+':'+JSON.stringify(v));};
// 1) 客栈端到端: var6=4 价, 扣款≥4, 全队治愈(多行脚本 CE5)
out.goldDelta=t.gold0!=null?gm.gold()-t.gold0:null;
out.hp=[a.hp,a.mhp];out.mp=[a.mp,a.mmp];out.var6=T.$gameVariables.value(6);
CHK('innRest',t.gold0!=null&&gm.gold()===t.gold0-4&&a.hp>=a.mhp-1&&a.mp>=a.mmp-1&&out.var6===4);
// 2) API 电池
try{out.innPrice=[gm.innPrice(1),gm.innPrice(2),gm.innPrice(5)];CHK('innPrice',JSON.stringify(out.innPrice)==='[4,8,20]');}catch(e){out.innPrice='EXC:'+e.message;fails.push('innPrice');}
try{out.actorName=T.$gameActors&&T.$gameActors.actor(1)&&T.$gameActors.actor(1).name;CHK('gameActors',!!out.actorName);}catch(e){out.actorName='EXC:'+e.message;fails.push('gameActors');}
try{const ac=T.$gameActors.actor(1);ac.addOwnTalent(102);out.talent=JSON.stringify(ac._ownTalents);CHK('addOwnTalent',JSON.stringify(ac._ownTalents)==='[102]');}catch(e){out.talent='EXC:'+e.message;fails.push('addOwnTalent');}
try{out.chLevel=(gm.changeLevel(3),gm.battleMembers().map(x=>x.level));CHK('changeLevel',Array.isArray(out.chLevel)&&out.chLevel.every(l=>l===3));}catch(e){out.chLevel='EXC:'+e.message;fails.push('changeLevel');}
try{out.surrender=(gm.addSurrenderedEnemy(114),gm.hasSurrenderedEnemy(114));CHK('surrender',out.surrender===true);}catch(e){out.surrender='EXC:'+e.message;fails.push('surrender');}
try{out.misc=[gm.inBattle(),gm.menuActor()?gm.menuActor().name:null,gm.gainWinPoint(1),gm.changePvpLevel(1),gm.addPvpCount()];CHK('miscNoThrow',Array.isArray(out.misc));}catch(e){out.misc='EXC:'+e.message;fails.push('misc');}
try{out.downLevel=T.$gameActors.actor(1).changeLevel(1,false);CHK('actorChangeLevel',out.downLevel===1);}catch(e){out.downLevel='EXC:'+e.message;fails.push('actorChangeLevel');}
out.allOk=fails.length===0;out.fails=fails;
return JSON.stringify(out);})()
